Ключевым элементом для работы с наборами данных является ListView. И нередко бывает важно продумать, какие инструменты использовать для управления данными в ListView. Одним из таких инструментов является контекстное меню. Элемент ListView позволяет прикрепить к каждому элементу контекстное меню через свойство **ContextActions**.



Итак, для работы с контекстным меню создадим новый проект. В качестве объектов с которыми будем работать, возьмем класс Phone



```c#

public class Phone
{
    public string Title { get; set; }
    public string Company { get; set; }
    public int Price { get; set; }
}
```



Далее добавим в проект модель **PhoneViewModel**, через которую мы будем взаимодействовать с объектами Phone:



```c#

using System.ComponentModel;

namespace HelloApp
{
    public class PhoneViewModel : INotifyPropertyChanged
    {
        public event PropertyChangedEventHandler PropertyChanged;
        public Phone Phone { get; set; }
        public PhonesListViewModel ListViewModel { get; set; }
        public PhoneViewModel()
        {
            Phone = new Phone();
        }
        public string Title
        {
            get { return Phone.Title; }
            set
            {
                if (Phone.Title != value)
                {
                    Phone.Title = value;
                    OnPropertyChanged("Title");
                }
            }
        }
        public string Company
        {
            get { return Phone.Company; }
            set
            {
                if (Phone.Company != value)
                {
                    Phone.Company = value;
                    OnPropertyChanged("Company");
                }
            }
        }
        public int Price
        {
            get { return Phone.Price; }
            set
            {
                if (Phone.Price != value)
                {
                    Phone.Price = value;
                    OnPropertyChanged("Price");
                }
            }
        }
        protected void OnPropertyChanged(string propName)
        {
            if (PropertyChanged != null)
                PropertyChanged(this, new PropertyChangedEventArgs(propName));
        }

    }
}
```



Кроме свойств-надстроек над свойствами объекта Phone здесь есть свойство, которое представляет модель PhonesListViewModel - объект списка, в котором будет находиться текущий объект PhoneViewModel. И далее добавим в проект новый класс **PhonesListViewModel**:



```c#

using System.Collections.ObjectModel;
using System.Windows.Input;
using Xamarin.Forms;

namespace HelloApp
{
    public class PhonesListViewModel
    {
        public ObservableCollection<PhoneViewModel> Phones { get; set; }
        public ICommand MoveToTopCommand { protected set; get; }
        public ICommand MoveToBottomCommand { protected set; get; }
        public ICommand RemoveCommand { protected set; get; }
        public PhonesListViewModel()
        {
            Phones = new ObservableCollection<PhoneViewModel>
            {
                new PhoneViewModel { Title="Pixel 5", Price=55000, Company="Google", ListViewModel=this},
                new PhoneViewModel {Title="Xiaomi Mi 10", Price= 28000, Company="Xiaomi", ListViewModel=this},
                new PhoneViewModel {Title="iPhone 12 Pro", Price=30000, Company="Apple", ListViewModel=this },
                new PhoneViewModel {Title="Galaxy S 10", Price=60000, Company="Samsung", ListViewModel=this },
                new PhoneViewModel {Title="Huawei P40 Pro", Price=36000, Company="Huawei", ListViewModel=this }
            };

            MoveToTopCommand = new Command(MoveToTop);
            MoveToBottomCommand = new Command(MoveToBottom);
            RemoveCommand = new Command(Remove);
        }

        private void MoveToTop(object phoneObj)
        {
            PhoneViewModel phone = phoneObj as PhoneViewModel;
            if (phone == null) return;
            int oldIndex = Phones.IndexOf(phone);
            if (oldIndex > 0)
                Phones.Move(oldIndex, oldIndex - 1);
        }
        private void MoveToBottom(object phoneObj)
        {
            PhoneViewModel phone = phoneObj as PhoneViewModel;
            if (phone == null) return;
            int oldIndex = Phones.IndexOf(phone);
            if (oldIndex < Phones.Count-1)
                Phones.Move(oldIndex, oldIndex + 1);
        }
        private void Remove(object phoneObj)
        {
            PhoneViewModel phone = phoneObj as PhoneViewModel;
            if (phone == null) return;

            Phones.Remove(phone);
        }
    }
}
```



Для хранения данных определена коллекция Phones, которая инициализируется в конструкторе.



Кроме этой коллекции в классе определены три команды. Команда MoveToTopCommand поднимает элемент на одну позицию вверх в списку (в реальности это выглядит как перемещение ближе к началу коллекции Phones). Команда MoveToBottomCommand, наоборот, опускает элемент на одну позицию вниз. А команда RemoveCommand удаляет элемент из списка.






В коде C# у главной страницы MainPage определим контекст данных:



```c#

using System;
using Xamarin.Forms;

namespace HelloApp
{
    public partial class MainPage : ContentPage
    {
        public MainPage()
        {
            InitializeComponent();
            this.BindingContext = new PhonesListViewModel();
        }
    }
}
```



В коде XAML определим список для вывода объектов, к каждому из которых прикрепим контекстное меню:



```xml

<?xml version="1.0" encoding="utf-8" ?>
<ContentPage xmlns="http://xamarin.com/schemas/2014/forms"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             x:Class="HelloApp.MainPage">
  <StackLayout>
    <ListView ItemsSource="{Binding Phones}" HasUnevenRows="True">
      <ListView.ItemTemplate>
        <DataTemplate>
          <ViewCell>
            <ViewCell.ContextActions>
              <MenuItem Text="Вверх" 
					Command="{Binding Path=ListViewModel.MoveToTopCommand}" CommandParameter="{Binding}" />
              <MenuItem Text="Вниз" 
					Command="{Binding Path=ListViewModel.MoveToBottomCommand}" CommandParameter="{Binding}" />
              <MenuItem Text="Удалить" 
					Command="{Binding Path=ListViewModel.RemoveCommand}" CommandParameter="{Binding}" />
            </ViewCell.ContextActions>
            <ViewCell.View>
              <StackLayout>
                <Label Text="{Binding Title}" FontSize="Medium" />
                <Label Text="{Binding Company}" FontSize="Small" />
                <Label Text="{Binding Price}" FontSize="Small" />
              </StackLayout>
            </ViewCell.View>
          </ViewCell>
        </DataTemplate>
      </ListView.ItemTemplate>
    </ListView>
</StackLayout>
</ContentPage>
```



Для определения меню применяется свойство **ContextActions** объекта ViewCell, который представляет собой отдельный элемент. Каждый пункт в этом меню представляет элемент **MenuItem**. У MenuItem можно определить команду и параметр, который будет пределаться команде при ее выполнении. В данном примере будут вызываться команды из PhonesListViewModel, которым будет передаваться текущий объект, для которого вызвано контекстное меню.



И если мы запустим приложение и одним долгим касанием нажмем на какой-нибудь элемент списка, то отобразится контекстное меню:



![контекстное меню в mvvm в xamarin forms](/uploads/course-lectures/40ac31e9b673175a4169c9d515569450adda3c13.png)



При этом надо отметить, что на разных ОС (даже на разных вериях одной ОС Android) визуально контекстное меню может выглядеть иначе.



Хотя здесь элементы меню используют команды и их параметры, однако нам в принцпе не обязательно использовать контекстное меню именно в контексте MVVM. Так, у каждого элемента меню есть стандартное событие `Clicked`, для которого мы можем определить в коде обработчик. Например:



```xml

<MenuItem Text="Show" Clicked="Show" />
```



А в коде прописать какой-нибудь метод обработки:



```c#

private async void Show(object sender, EventArgs e)
{
    await DisplayAlert("Контекстное меню", "Пункт Show", "OK");
}
```



В тоже время в MVVM использование контекстного меню имеет свои плюсы, в частности, возможность передачи параметра.

Кроме обычных файлов для хранения данных мы можем использовать локальные базы данных. Наиболее популярной системой баз данных для локальных приложений является SQLite, поэтому рассмотрим общие принципы работы с этой СУБД.



Для работы с SQLite можно использовать разные подходы и библиотеки. Рекомендуемой библиотекой является **SQLite.NET**, которая представляет простое ORM-решение (Object Relational Mapping) для Xamarin. Она позволяет работать с базой данных как с хранилищем объектов и манипулировать данными как объектами стандартных классов C# без использования выражений на языке SQL. И вначале добавим в главный проект в узел References с помощью менеджера NuGet эту библиотеку **sqlite-net-pcl**:



![sqlite in xamarin forms](/uploads/course-lectures/e95356c24d56ce07c6a80cc9f9595506864abe24.png)



Следует отметить, что в Nuget можно найти много похожих библиотек с подобным названием. У нужной библиотеки будут следующие данные:





- Автор: SQLite-net

- Id: sqlite-net-pcl




Вначале определим класс, объекты которого будут храниться в базе данных. Добавим в главный проект следующий класс Friend:



```c#

using SQLite;

namespace HelloApp
{
    [Table("Friends")]
    public class Friend
    {
        [PrimaryKey, AutoIncrement, Column("_id")]
        public int Id { get; set; }

        public string Name { get; set; }
        public string Email { get; set; }
        public string Phone { get; set; }
    }
}
```



Класс Friend выступает в качестве модели приложения. Этот класс использует атрибуты, которые позволяют настроить его отображение на таблицу в бд. Для настройки мы можем использовать следующие атрибуты:





- [PrimaryKey] : применяется к свойству типа int и указывает, что столбец в таблице, который соответствует этому свойству, будет выполнять роль первичного ключа. Составные ключи не поддерживаются

- [AutoIncrement] : применяется к свойству типа int и указывает, что столбец в таблице, который соответствует этому свойству, будет инкрементировать значение на единицу при добавлении нового элемента

- [Column(name)] : задает сопоставление свойства со столбцом в таблице, который имеет имя name

- [Table(name)] : устанавливает название таблицы, которая будет соотвествовать данному классу

- [MaxLength(value)] : устанавливает максимальную длину для строковых свойств

- [Ignore] : указывает, что свойство будет игнорироваться. Это может быть полезно, если значение данного свойства не надо хранить в базе данных, и данное свойство не должно сопоставляться со столбцами из таблицы в бд

- [Unique] : гарантирует, что столбец, который соответствует свойству с этим атрибутом, будет иметь уникальные неповторяющиеся значения



При запросах к базе данных будет происходить автоматическое сопоставление типов данных из SQLite с типами данных из C#. Сопоставление типов можно описать следующей таблицей:



| C# | SQLite |
| --- | --- |
| int, long | integer, bigint |
| bool | integer (1 = true) |
| enum | integer |
| float | real |
| double | real |
| decimal | real |
| string | varchar, text |
| DateTime | numeric, text |
| byte[] | blob |






### Класс репозитория



Также создадим класс репозитория, через который будут идти все операции с данными:



```c#

using System.Collections.Generic;
using SQLite;

namespace HelloApp
{
    public class FriendRepository
    {
        SQLiteConnection database;
        public FriendRepository(string databasePath)
        {
            database = new SQLiteConnection(databasePath);
            database.CreateTable<Friend>();
        }
        public IEnumerable<Friend> GetItems()
        {
            return database.Table<Friend>().ToList();
        }
        public Friend GetItem(int id)
        {
            return database.Get<Friend>(id);
        }
        public int DeleteItem(int id)
        {
            return database.Delete<Friend>(id);
        }
        public int SaveItem(Friend item)
        {
            if (item.Id != 0)
            {
                database.Update(item);
                return item.Id;
            }
            else
            {
                return database.Insert(item);
            }
        }
    }
}
```



В конструкторе класса происходит создание подключения и базы данных (если она отсутствует). В качестве параметра извне будет передаваться путь к базе данных. При желании путь к бд можно определить и в самом конструкторе.



Для всех операций с данными используются методы, определенные в классе SQLiteConnection:





- Insert : добавляет объект в таблицу

- Get  : позволяет получить элемент типа T по id

- Table  : возвращает все объекты из таблицы

- Delete  : удаляет объект по id

- Update  : обновляет объект

- Query  : выполняет SQL-выражение и возвращает строки из таблицы в виде объектов типа T (относится к выражениям SELECT)

- Execute : выполняет SQL-выражение, но ничего не возвращает (относится к операциям. где не надо возвращать результат - UPDATE, INSERT, DELETE)



Если предполагается, что к базе данных может обращаться сразу несколько потоков, то для блокирования одновременных операций с бд в классе репозитории можно использовать блок **lock** с заглушкой, например:



```c#

SQLiteConnection database;
static object locker = new object();
//......................
 
public int DeleteItem(int id)
{
	lock(locker)
	{
        return database.Delete<Friend>(id);
	}
}
```



