        }
        // обработка нажатия кнопки добавления
        private async void CreateFriend(object sender, EventArgs e)
        {
            Friend friend = new Friend();
            FriendPage friendPage = new FriendPage();
            friendPage.BindingContext = friend;
            await Navigation.PushAsync(friendPage);
        }
	}
}
```



Интерфейс страницы **FriendPage.xaml** для отображения одного объекта:



```xml

<?xml version="1.0" encoding="utf-8" ?>
<ContentPage xmlns="http://xamarin.com/schemas/2014/forms"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             x:Class="HelloApp.FriendPage" Title="Информация о друге">
  <StackLayout>
    <Label Text="Имя" />
    <Entry Text="{Binding Name}" />
    <Label Text="Email" />
    <Entry Text="{Binding Email}" />
    <Label Text="Телефон" />
    <Entry Text="{Binding Phone}" />
    <StackLayout Orientation="Horizontal">
      <Button Text="Сохранить" Clicked="SaveFriend" />
      <Button Text="Удалить" Clicked="DeleteFriend" />
      <Button Text="Отмена" Clicked="Cancel" />
    </StackLayout>
  </StackLayout>
</ContentPage>
```



Файл связанного кода **FriendPage.xaml.cs**:



```c#

using System;
using Xamarin.Forms;
using Xamarin.Forms.Xaml;

namespace HelloApp
{
    public partial class FriendPage : ContentPage
    {
        public FriendPage()
        {
            InitializeComponent();
        }
        private async void SaveFriend(object sender, EventArgs e)
        {
            var friend = (Friend)BindingContext;
            if (!String.IsNullOrEmpty(friend.Name))
            {
                await App.Database.SaveItemAsync(friend);
            }
            await this.Navigation.PopAsync();
        }
        private async void DeleteFriend(object sender, EventArgs e)
        {
            var friend = (Friend)BindingContext;
            await App.Database.DeleteItemAsync(friend);
            await this.Navigation.PopAsync();
        }
        private async void Cancel(object sender, EventArgs e)
        {
            await this.Navigation.PopAsync();
        }
    }
}
```

Хотя можно создать приложение на одном языке, однако чем больше языков оно будет поддерживать, тем больше оно будет распространено, и в итоге тем больше будет прибыль от приложения. Рассмотрим, как создать в Xamarin Forms многоязычное приложение.

Допустим, у нас определена в приложении страница с простеньким интерфейсом:

```xml
<StackLayout>
  <Label x:Name="myLabel" FontSize="Large" />
  <Entry x:Name="myEntry" />
  <Button x:Name="myButton" FontSize="Large" />
</StackLayout>
```

Рассмотрим, как можно локализовать эту форму на несколько языков.

Чтобы определить в приложении локализацию, нам надо использовать файлы ресурсов. Основной файл ресурсов (RESX) будет содержать все строковые значения для языка по умолчанию. Добавим в проект файл ресурсов. Для этого нажмем на проект правой кнопкой мыши и выберем **Add -> New Item...**. В окне добавления нового элемента выберем тип **Resources Files**. Назовем его просто **Resource.resx**:

![resources in xamarin](/uploads/course-lectures/d4a4bdfc9b4e6f8045bb51da1be6acd92bb0af6b.png)

После добавления в Visual Studio новый файл автоматически откроется в дизайнере ресурсов, который представляет собой таблицу. Таблица имеет несколько столбцов. В столбце Name указывается название ресурса, а в столбце Value - его значение. Опционально можно в третьем столбце указать комментарий по поводу использования данного ресурса. Допустим, у нас будет простейшая форма ввода на странице с меткой, текстовым полем и кнопкой. То есть мы можем создать три ресурса для текстовых значений этих элементов. Добавим эти элементы в таблицу:

![resource editor in xamarin](/uploads/course-lectures/0989741419507b682c3e1404f24b7e37dca6e6b3.png)

Пусть это будет англоязычная культура по умолчанию, хотя это может быть любая другая культура.

Чтобы добавить поддержку нескольких языков, нам надо создать файлы ресурсов для соответствующих языков. Согласно соглашениям по именованию названия этих ресурсов должны иметь одно и то же имя, после которого через точку идет код языка. Например, если для языка по умолчанию файл ресурсов называется **Resource.resx**, то для немецкого языка, код которого - `de`, название файла будет Resource.de.resx , для русского, например, - **Resource.ru.resx**, для испанского - **Resource.es.resx** и т.д.

Некоторые языковые культуры имеют разные ответвления, например, португальский в Португалии будет отличаться от португальского в Бразилии. Чтобы более точно таргетировать файл ресурсов на определенную языковую культуру, мы можем использовать полное название локали. Например, для бразильского португальского: Resource.pt-BR.resx

Скопируем файл ресурсов и вставим его в проект. Переименуем новый файл в **Resource.ru.resx**. Изменим в нем определения ресурсов:

![](/uploads/course-lectures/b9e99d9532052c48e787a6b892abd71fd5204fa7.png)

Попутно можно определить файлы ресурсов и для других языков. Добавление ресуросов происходит только в главный проект, остальные проекты мы вообще не трогаем. В итоге в главном проекте будет примерно следующая структура:

![localization in xamarin.forms](/uploads/course-lectures/fd88fd410e3696fd221f6ec8de323a5e7ecb8bdf.png)

Теперь для того, чтобы локализовать элементы интерфейса в коде, мы можем присвоить их тексту определенный ресурс из файла ресурсов. Например, в конструкторе класса страницы в файле кода с# можно прописать следующее:

```c#
using Xamarin.Forms;

namespace HelloApp
{
    public partial class MainPage : ContentPage
    {
        public MainPage()
        {
            InitializeComponent();
            myLabel.Text = Resource.Header;
            myEntry.Placeholder = Resource.LoginText;
            myButton.Text = Resource.SaveButton;
        }
    }
}
```

То есть название класса ресурса, которое совпадает с именем файла ресурса - "Resource", после которого идет конкретный ресурс. Причем значения для ресурсов будут браться из того файла, который соответствует языковой культуре мобильного устройства. Например:

![localization in xamarin](/uploads/course-lectures/b16e7132f62e69b97344ed782514c275ae646ed4.png)

В прошлой теме был создан проект и ряд ресурсов, позволяющих локализовать приложение. Однако просто установки в коде нужного ресурса бывает недостаточно. Нужно явным образом указать требуемую языковую культуру для определенной платформы.

Поскольку каждая платформа требует определенного подхода, то нам надо использовать класс `DependencyService`, который позволит сопоставить нужные зависимости.

Вначале добавим в главный проект интерфейс ILocalize:

```c#
using System.Globalization;
public interface ILocalize
{
    CultureInfo GetCurrentCultureInfo();
}
```

Его единственный метод будет определять языковую культуру мобильного устройства.

Теперь добавим в проект для iOS следующий класс Localize:

```c#
using Foundation;
using Xamarin.Forms;
[assembly: Dependency(typeof(HelloApp.iOS.Localize))]
namespace HelloApp.iOS
{
    public class Localize : ILocalize
    {
        public System.Globalization.CultureInfo GetCurrentCultureInfo()
        {
            var netLanguage = "en";
            var prefLanguage = "en-US";
            if (NSLocale.PreferredLanguages.Length > 0)
            {
                var pref = NSLocale.PreferredLanguages[0];
                netLanguage = pref.Replace("_", "-"); // заменяет pt_BR на pt-BR
            }
            System.Globalization.CultureInfo ci = null;
            try
            {
                ci = new System.Globalization.CultureInfo(netLanguage);
            }
            catch
            {
                ci = new System.Globalization.CultureInfo(prefLanguage);
            }
            return ci;
        }
    }
}
```

Реализация этого класса использует массив `NSLocale.PreferredLanguages` для определения языковой культуры.

При получении языка на устройстве iOS нам следует учитывать следующий аспект. Пользователь теоретически может установить в качестве культуры, например, "en-ES". Например, если пользователь живет в Испании и в качестве региона выставил Испанию, однако захотел в качестве языка использовать английский. Культура "en-ES" не соответствует ни однйо из культур в .NET, поэтому программа может вывалиться в ошибку. Чтобы ее избежать, здесь применяется блок `try...catch`, где в случае неудачи получить установленную культуры мы получаем предпочтительную культуру - "en-US".

Некоторые системные элементы управления iOS переводит автоматически (например, элемент Picker). Но чтобы указать системе на необходимость перевода, нам надо внести в файл **Info.plist**, который имеется в проекте, соответствующие определения языковых культур. Info.plist представляет обычный xml-файл, поэтому откроем его в каком-нибудь текстовом редакторе. Он выглядит примерно так:

```xml
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
  <dict>
  <!---->
  </dict>
</plist>
```

В пределах элемента `dict` добавим определения языков. В моем случае язык по умолчанию английский (en) и две дополнительных языковых культуры: русскоязычная (ru) и немецкая (de). Поэтому я добавляю следующие строки:

```xml
<key>CFBundleLocalizations</key>
<array>
	<string>de</string>
	<string>ru</string>
</array>
<key>CFBundleDevelopmentRegion</key>
<string>en</string>
```

### Настройка проекта для Android

В проект для Androida добавим следующий класс:

```c#
using Xamarin.Forms;
[assembly: Dependency(typeof(HelloApp.Droid.Localize))]
namespace HelloApp.Droid
{
    public class Localize : ILocalize
    {
        public System.Globalization.CultureInfo GetCurrentCultureInfo()
        {
            var androidLocale = Java.Util.Locale.Default;
            var netLanguage = androidLocale.ToString().Replace("_", "-");
            return new System.Globalization.CultureInfo(netLanguage);
        }
    }
}
```

Опять же это реализация интерфейса ILocalize, которая использует объект `Java.Util.Locale.Default` для определения культуры.

### Настройка проекта для UWP

Также добавим реалзицию интерфейса ILocalize в проект для UWP:

```c#
using System.Globalization;
using Xamarin.Forms;
[assembly: Dependency(typeof(HelloApp.UWP.Localize))]
namespace HelloApp.UWP
{
    public class Localize : ILocalize
    {
        public System.Globalization.CultureInfo GetCurrentCultureInfo()
        {
            return CultureInfo.CurrentUICulture;
        }
    }
}
```

Языковая культура приложения должна определяться как можно раньше. В частности, это можно сделать при открытии стартовой страницы приложения. Итак, добавим в конструктор класса **App** в главном проекте определения языковой культуры:

```c#
public partial class App : Application
{
    public App()
    {
		InitializeComponent();

        if (Device.RuntimePlatform != Device.UWP)
        {
            Resource.Culture = DependencyService.Get<ILocalize>()
                                .GetCurrentCultureInfo();
        }
        MainPage = new MainPage();
    }
}
```

И поскольку фреймворк автоматически распознает язык на устройстве Windows 10, нам нет нужды устанавливать его вручную, поэтому сначала в коде проверяем тип платформы `if (Device.RuntimePlatform != Device.UWP)`

В прошлых темах мы рассмотрели локализацию в коде C#, но гораздо проще было бы локализовать элементы интерфейса сразу же в xaml. Для этого возьмем проект из прошлой темы.

Чтобы добавить в приложение возможность локализации элементов xaml, надо добавить класс расширения разметки. Итак, добавим в главный проект следующий класс:

```c#
using System;
using Xamarin.Forms;
using Xamarin.Forms.Xaml;
using System.Resources;
using System.Globalization;
using System.Reflection;

namespace HelloApp
{
    [ContentProperty("Text")]
    public class TranslateExtension : IMarkupExtension
    {
        readonly CultureInfo ci;
        const string ResourceId = "HelloApp.Resource";

        public TranslateExtension()
        {
            ci = DependencyService.Get<ILocalize>().GetCurrentCultureInfo();
        }

        public string Text { get; set; }

        public object ProvideValue(IServiceProvider serviceProvider)
        {
            if (Text == null)
                return "";

            ResourceManager resmgr = new ResourceManager(ResourceId, 
						typeof(TranslateExtension).GetTypeInfo().Assembly);

            var translation = resmgr.GetString(Text, ci);

            if (translation == null)
            {
                translation = Text; 
            }
            return translation;
        }
    }
}
```

В строке `const string ResourceId = "HelloApp.Resource";` устанавливаются ресурсы для локализации. Так как у меня пространство имен проекта называется `HelloApp`, а файл ресурсов по умолчанию размещен в корне проекта и называется `Resource.resx`, то полное имя ресурса будет `HelloApp.Resource`.

Для извлечения ресурсов используется класс `ResourceManager` и его метод `GetString()`

Теперь применим данный класс в xaml:

```xml
<?xml version="1.0" encoding="utf-8" ?>
<ContentPage xmlns="http://xamarin.com/schemas/2014/forms"
					   xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
					   x:Class="HelloApp.MainPage"
  xmlns:local="clr-namespace:HelloApp;assembly=HelloApp">
  <StackLayout>

	<Label x:Name="myLabel" FontSize="Large" Text="{local:Translate Header}" />
    <Entry x:Name="myEntry" Placeholder="{local:Translate LoginText}" />
    <Button x:Name="myButton" FontSize="Large"  Text="{local:Translate SaveButton}" />
  </StackLayout>
</ContentPage>
```

Чтобы получить доступ к классу, надо подключить текущее пространство имен проекта: `xmlns:local="clr-namespace:HelloApp;assembly=HelloApp"`

Затем мы можем использовать привязку у тех свойствам элементов, которые надо локализовать: `Text="{local:Translate Header}"`. В данном случае local ссылается на текущее пространство имен, "Translate" ссылается на класс `TranslateExtension` - по умолчанию суффикс Extension отбрасывается. И затем указывается называется имя ресурса, к которому идет привязка.

В итоге мы можем убрать локализацию из класса приложения App, которая была определена в прошлых темеах, теперь он будет просто создавать стартовую страницу:

```c#
public partial class App : Application
{
    public App()
    {
		InitializeComponent();

        MainPage = new MainPage();
    }
}
```

Взаимодействие с сервером является одним из неотъемлемых возможностей многих мобильных приложений. Приложение может получать данные с сервера, или, наоборот, отправлять некоторые данные. Но чтобы взаимодействовать с сервером, необходимо подключение к сети, которое не не всегда может быть доступно в силу тех или иных причин. С помощью специального класса **Connectivity** из пакета **Xamarin.Essentials**, который добавляется в проект Xamarin Forms по умолчанию, мы можем проверить подключение к интернету.

Платформы имеют ряд ограничений при работе с сетью, которые нам надо учитывать. В частности, для получения состояния сети в Android, надо задать соответствующие разрешения. Для этого перейдем в проекте для Android к папке **Properties**, откроем файл **AssemblyInfo.cs** и добавим в него следующую строку:

```c#
[assembly: UsesPermission(Android.Manifest.Permission.AccessNetworkState)]
```

Либо также в проекте для Android и также в папке **Properties** мы можем добавить в файл **AndroidManifest.xml** в узел **manifest** строку:

```xml
<uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />
```

Для проектов для iOS и UWP никаких изменений не требуется.

Какой функционал предоставляет класс Connectivity? Прежде всего с помощью свойства **Connectivity.NetworkAccess** он позволяет проверить наличие доступа к сети. Это свойство представляет перечисление **NetworkAccess**, которое определяет следующие значения:

- Internet : есть подключение к интернету

- ConstrainedInternet : есть ограниченный доступ, для которого требуются учетные данные

- Local : имеется доступ только к локальной сети

- None : доступ к сети отсутствует

- Unknown : невозможно определить состояние подключения

Таким образом, с помощью данного перечисления мы можем проверить состояние подключения:

```c#
var current = Connectivity.NetworkAccess;

if (current == NetworkAccess.Internet)
{
    // некоторые действия 
}
```

Кроме того, класс Connectivity определяет свойство **Connectivity.ConnectionProfiles**, которое содержит набор доступых профилей для доступа к сети. Каждый профиль представлен перечислением **ConnectionProfile**, которое определяет следующие значения:

- Bluetooth : есть доступ через Bluetooth

- Cellular : подключение через мобильную связь

- Ethernet : подключение через кабель Ethernet

- WiFi : подключение через WiFi

- Unknown : неизвестный тип подключения

Проверка типа подключения:

```c#
var profiles = Connectivity.ConnectionProfiles;
if (profiles.Contains(ConnectionProfile.WiFi))
{
    // если активно подключение через Wi-Fi
}
```

Кроме того, класс определяет событие **Connectivity.ConnectivityChanged**, которое генерируется при изменения состояния подключения.

Используем функционал класса Connectivity. Для этого в классе MainPage определим следующий код:

```c#
using System;
using Xamarin.Forms;
using Xamarin.Essentials;
using System.Linq;

namespace HelloApp
{
    public partial class MainPage : ContentPage
    {
        Label connectionStateLbl;
        public MainPage()
        {
            connectionStateLbl = new Label
            {
                FontSize = Device.GetNamedSize(NamedSize.Large, typeof(Label)),
                HorizontalOptions = LayoutOptions.Center,
                VerticalOptions = LayoutOptions.Center,
            };
            Content = new StackLayout
            {
                Children = { connectionStateLbl}
            };

            Connectivity.ConnectivityChanged += Current_ConnectivityChanged;
        }

        protected override void OnAppearing()
        {
            base.OnAppearing();
            CheckConnection();
        }
        // обработка изменения состояния подключения
        private void Current_ConnectivityChanged(object sender, ConnectivityChangedEventArgs e)
        {
            CheckConnection();
        }
        // получаем состояние подключения
        private void CheckConnection()
        {
            if(Connectivity.NetworkAccess == NetworkAccess.Internet)
            {
                connectionStateLbl.Text = "Доступные типы подключений:\n";
                var profiles = Connectivity.ConnectionProfiles;
                foreach (var profile in profiles)
                {
                    connectionStateLbl.Text += $"{profile.ToString()} \n";
                }
            }
            else
            {
                connectionStateLbl.Text = "Подключение отсутствует";
            }
        }
    }
}
```

На странице определена метка, которая будет выводить информацию о подключении. Если полноценного подключения к интернету нет, выводим одно сообщение:

![подключение к интернету в xamarin forms](/uploads/course-lectures/e6b91449d0e8dbc9cee94ee506db06e2c7cc938b.png)

При наличии доступа к сети будут отображаться все доступные типы подключения:

![управление подключением к интернету в xamarin forms](/uploads/course-lectures/b8adec085c34527cdfbb7dbe78b07b65c4729881.png)

В прошлой теме мы рассмотрели, как отправлять запрос к внешнему серверу. Теперь рассмотрим, как мы можем отправлять запросы самых различных типов - GET, POST, PUT, DELETE. Для тестирования взаимодействия с сервером приложения на Xamarin создадим веб-сервис (либо можно взять уже имеющийся сервер вне зависимсти от технологии бекэнда). В качестве основы для веб-сервиса выберем технологию ASP.NET Core. Для этого создадим новый проект по типу **ASP.NET Core Web Application**



![веб-сервис для xamarin forms](/uploads/course-lectures/7bfa48a67e0c779cc11e48fe629bce214da4b49a.png)



Назовем **SocialService**:



